head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > ignoreNonEditableCell]<br/>키보드로 포커스 이동 시 편집 불가 상태(disabled, readonly)인 Body Cell 을 건너 뛸지 설정합니다.",
    "validation" : [
        "true 설정 시, 키보드(Tab, Enter, 방향키)로 포커스 이동 시 readonly 또는 disabled 상태의 Body Cell 은 건너 뛰고 편집 가능한 다음 Cell 로 포커스를 이동합니다.",
        "false 설정 시, 키보드(Tab, Enter, 방향키)로 포커스 이동 시 readonly 또는 disabled 상태의 Body Cell 도 포커스가 이동합니다.",
        "미설정 시, 키보드(Tab, Enter, 방향키)로 포커스 이동 시 readonly 또는 disabled 상태의 Body Cell 도 포커스가 이동합니다.",
        "ignoreNonEditableCell=true 인 경우 readOnlyTabIgnore 속성은 실질적으로 의미가 없어집니다.",
        "ignoreNonEditableCell 속성에 의해 건너 뛴 Body Cell 에 대해서는 oncellindexchange 이벤트가 발생하지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1(gdl_boolean)은 초기 selectedIndex 미적용 → 기본값(미설정='1') 명시 설정
    con_ignoreNonEditableCell.setValue("1");
    con_readOnlyTabIgnore.setValue("1");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - con_ignoreNonEditableCell : 공통 gdl_boolean → getText() ('' 미설정=속성제외 기본 false / 'true' / 'false')
//  - con_readOnlyTabIgnore     : gdl_boolean → getText() (ignoreNonEditableCell=true 일때 의미 없어짐 검증)
//  - focusMode="cell" 고정      : 키보드 셀 포커스 이동 확인용
//  - Body col2 = readOnly, col3 = disabled 로 고정 (편집 가능 셀: col1, col4)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vIgnore            = con_ignoreNonEditableCell.getText();
    let vReadOnlyTabIgnore = con_readOnlyTabIgnore.getText();

    // focusMode 는 키보드 포커스 이동 확인을 위해 cell 고정
    let properties = {
        focusMode : "cell"
    };

    // ignoreNonEditableCell : '' 미설정 시 속성 제외(기본 false)
    if (vIgnore === 'true') {
        properties.ignoreNonEditableCell = true;
    } else if (vIgnore === 'false') {
        properties.ignoreNonEditableCell = false;
    }

    // readOnlyTabIgnore : ignoreNonEditableCell=true 시 의미 없어짐 검증용
    if (vReadOnlyTabIgnore === 'true') {
        properties.readOnlyTabIgnore = true;
    } else if (vReadOnlyTabIgnore === 'false') {
        properties.readOnlyTabIgnore = false;
    }

    let cList = $c.gcm.createCList(properties);

    let lblDesc = '[전제] col2=readOnly(연회색 배경), col3=disabled(연노랑 배경) (편집 가능 셀: col1, col4)'
        + '\n[현재] ignoreNonEditableCell=' + (vIgnore === '' ? '(미설정=기본 false)' : vIgnore)
        + ', readOnlyTabIgnore=' + (vReadOnlyTabIgnore === '' ? '(미설정)' : vReadOnlyTabIgnore)
        + '\n[절차] col1 셀 클릭 후 Tab 또는 Enter(enterKeyMove=right 로 가로 이동) 또는 좌/우 방향키 입력 → col2(RO)/col3(DIS) 건너뛰고 col4 로 이동'
        + '\n[확인] 하단 출력의 이동 셀 위치 (건너뛴 셀은 oncellindexchange 미발생이라 출력되지 않음)';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // 포커스 이동 확인용 dataList 생성 (col1~col4, 6행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // target 생성 (4컬럼 Body 그리드)
    await scwin.createGridView(cList);

    // col2 = readOnly, col3 = disabled 설정 (편집 가능 셀 사이에 편집 불가 셀 배치)
    target1.setColumnReadOnly(1, true);
    target1.setColumnDisabled(2, true);

    // 첫번째 편집 가능 셀(col1)에 포커스
    target1.setFocusedCell(0, 0, true);
}



// 포커스 이동 확인용 데이터 (6행)
scwin.fillData = function () {
    let rows = [
        { col1: "A1", col2: "B1", col3: "C1", col4: "D1" },
        { col1: "A2", col2: "B2", col3: "C2", col4: "D2" },
        { col1: "A3", col2: "B3", col3: "C3", col4: "D3" },
        { col1: "A4", col2: "B4", col3: "C4", col4: "D4" },
        { col1: "A5", col2: "B5", col3: "C5", col4: "D5" },
        { col1: "A6", col2: "B6", col3: "C6", col4: "D6" }
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성
//  - enterKeyMove="right" : Enter 키를 세로(아래 행)가 아닌 가로(오른쪽 컬럼)로 이동시켜
//    Tab 과 동일하게 편집 불가 셀(readonly/disabled)을 건너뛰는 경로를 타게 함
//  - oncellindexchange : Tab/Enter/방향키 등으로 포커스 셀이 실제 이동할 때마다 발생
//    (ignoreNonEditableCell 로 건너 뛴 셀에서는 발생하지 않음 → 출력 로그로 확인)
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" enterKeyMove="right" readOnlyBackgroundColor="#D3D3D3" disabledBackgroundColor="#FFF9C4" style="width:520px;height:300px;" ev:oncellindexchange="scwin.target1_oncellindexchange">';
    s += '<w2:caption style="" id="caption1" value="ignoreNonEditableCell 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2(RO)"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3(DIS)"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 셀 포커스가 실제 이동(변경)될 때 호출 (oncellindexchange)
//  - Tab/Enter/방향키 입력으로 포커스 셀이 바뀔 때마다 이동 셀과 이전 셀 위치를 하단에 누적 출력
//  - ignoreNonEditableCell 로 건너 뛴 readonly/disabled 셀에서는 이 이벤트가 발생하지 않으므로,
//    출력된 이동 셀 시퀀스로 어느 셀을 건너 뛰었는지 확인 (예: col1 -> col4 로 바로 이동)
scwin.target1_oncellindexchange = function (rowIndex, columnIndex, oldRow, oldColumnIndex) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("oncellindexchange 발생 → 이동 셀 (row: " + rowIndex + ", col: " + columnIndex
        + "), 이전 셀 (row: " + oldRow + ", col: " + oldColumnIndex + ")");
}
